INSERT INTO _migration_621_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_015', 'topic_bece_science_matter', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A teacher gives a class a mixture of salt and sand and asks them to obtain pure dry salt from it.', 'structured', NULL, NULL, '(a) Warm water dissolves the salt quickly, but sand does not dissolve in water at all (1). (b) The mixture is poured through filter paper held in a funnel — this is filtration (1); the insoluble sand stays on the paper as the residue while the salt solution passes through as the filtrate (1). (c) The filtrate is heated so that the water evaporates (1); the salt is left behind as solid crystals, which are then dried (1).', '(a) Warm water dissolves the salt quickly, but sand does not dissolve in water at all (1). (b) The mixture is poured through filter paper held in a funnel — this is filtration (1); the insoluble sand stays on the paper as the residue while the salt solution passes through as the filtrate (1). (c) The filtrate is heated so that the water evaporates (1); the salt is left behind as solid crystals, which are then dried (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_016', 'topic_bece_science_energy', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Which sequence correctly shows the energy transformations in a hydroelectric power station such as Akosombo?', 'multiple_choice', NULL, '["A. Electrical energy → kinetic energy → potential energy","B. Chemical energy of coal → heat energy → electrical energy","C. Potential energy of stored water → kinetic energy of moving water → kinetic energy of turbines → electrical energy","D. Light energy → sound energy → electrical energy"]', 'C', 'Water held behind the dam has gravitational potential energy; as it falls through the penstock it gains kinetic energy, which spins the turbines, and the generators convert that movement into electrical energy. (A hydroelectric station burns no coal, and the chain cannot begin with electrical energy, which is the output, not the input.) Therefore the correct answer is C: Potential energy of stored water → kinetic energy of moving water → kinetic energy of turbines → electrical energy.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Sequence', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_017', 'topic_bece_science_energy', 'subj_bece_science', 'exam_bece', NULL, NULL, 'No machine is 100% efficient. What happens to the input energy that is not converted into useful work?', 'multiple_choice', NULL, '["A. It is destroyed by the machine","B. It is stored inside the machine forever","C. It changes back into the original fuel","D. It is changed into other forms, such as heat and sound, that are not useful"]', 'D', 'By the law of conservation of energy, energy cannot be created or destroyed. Friction between moving parts converts some of the input energy into heat and sound, which do no useful work, so the useful output is always less than the input. (Energy is never destroyed, and the wasted heat does not turn back into fuel.) Therefore the correct answer is D: It is changed into other forms, such as heat and sound, that are not useful.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_018', 'topic_bece_science_energy', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State the law of conservation of energy, and name the energy transformation that takes place when a torch is switched on.', 'short_answer', NULL, NULL, 'Energy cannot be created or destroyed; it can only be changed from one form to another. In a torch, chemical energy in the battery changes into electrical energy and then into light (and a little heat).', 'The law of conservation of energy states that energy cannot be created or destroyed but can only be transformed from one form to another. When a torch is switched on, the chemical energy stored in the battery becomes electrical energy in the circuit, and the bulb converts this into light energy with a small amount of heat.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_019', 'topic_bece_science_energy', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A 2 kg bag of rice is lifted from the floor onto a shelf 3 m high. Taking g = 10 m/s², calculate the potential energy gained by the bag.', 'calculation', NULL, NULL, '60 J', 'Potential energy gained = m × g × h = 2 kg × 10 m/s² × 3 m = 60 J. Answer: the bag gains 60 J of potential energy.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_020', 'topic_bece_science_energy', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Ghana needs more sources of electricity for homes and schools.', 'structured', NULL, NULL, '(a) A renewable energy source is one that is naturally replaced and will not run out, such as sunlight, wind or flowing water (1). (b) Any two of: solar energy (sunlight), wind energy, hydroelectric power (flowing water), biomass (1 each). (c) Advantage: sunlight is free and clean and produces no smoke or greenhouse gases (1). Disadvantage: it works only when the sun shines, so batteries or another source are needed at night or on cloudy days (1).', '(a) A renewable energy source is one that is naturally replaced and will not run out, such as sunlight, wind or flowing water (1). (b) Any two of: solar energy (sunlight), wind energy, hydroelectric power (flowing water), biomass (1 each). (c) Advantage: sunlight is free and clean and produces no smoke or greenhouse gases (1). Disadvantage: it works only when the sun shines, so batteries or another source are needed at night or on cloudy days (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT INTO _migration_621_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_015_a', 'q_bece_intsci_s3_015', 'a', 'Explain why the mixture is first stirred with warm water.', '1', 'Warm water dissolves the salt quickly, but sand does not dissolve in water at all (1).', '1'),
('sqp_q_bece_intsci_s3_015_b', 'q_bece_intsci_s3_015', 'b', 'Describe how the sand is then separated from the salt solution.', '2', 'The mixture is poured through filter paper held in a funnel — this is filtration (1); the insoluble sand stays on the paper as the residue while the salt solution passes through as the filtrate (1).', '2'),
('sqp_q_bece_intsci_s3_015_c', 'q_bece_intsci_s3_015', 'c', 'Describe how pure dry salt is obtained from the filtrate.', '2', 'The filtrate is heated so that the water evaporates (1); the salt is left behind as solid crystals, which are then dried (1).', '3'),
('sqp_q_bece_intsci_s3_020_a', 'q_bece_intsci_s3_020', 'a', 'Explain what is meant by a renewable energy source.', '1', 'A renewable energy source is one that is naturally replaced and will not run out, such as sunlight, wind or flowing water (1).', '1'),
('sqp_q_bece_intsci_s3_020_b', 'q_bece_intsci_s3_020', 'b', 'Name two renewable energy sources that can be used in Ghana.', '2', 'Any two of: solar energy (sunlight), wind energy, hydroelectric power (flowing water), biomass (1 each).', '2'),
('sqp_q_bece_intsci_s3_020_c', 'q_bece_intsci_s3_020', 'c', 'State one advantage and one disadvantage of using solar energy.', '2', 'Advantage: sunlight is free and clean and produces no smoke or greenhouse gases (1). Disadvantage: it works only when the sun shines, so batteries or another source are needed at night or on cloudy days (1).', '3');
INSERT INTO _migration_621_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_621_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_621_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_621_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_621_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_621_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_621_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_621_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_621_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_621_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_621_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_621_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 6 THEN 1 ELSE 0 END;
